body {
  min-height: 100vh;
  background:
    radial-gradient(1200px 600px at 10% -10%, rgba(124, 156, 255, 0.12), transparent 60%),
    radial-gradient(900px 500px at 110% 10%, rgba(181, 140, 255, 0.10), transparent 60%),
    var(--bg-0);
}

.page {
  max-width: 820px;
  margin: 0 auto;
  padding: 64px 24px 96px;
}

.hero {
  text-align: center;
  margin-bottom: 40px;
}

.hero .eyebrow {
  display: inline-block;
  font-size: 12px;
  letter-spacing: 0.18em;
  text-transform: uppercase;
  color: var(--text-muted);
  background: var(--bg-2);
  border: 1px solid var(--border);
  padding: 6px 12px;
  border-radius: 999px;
  margin-bottom: 18px;
}

.hero h1 {
  font-size: 40px;
  line-height: 1.15;
  margin: 0 0 12px;
  background: linear-gradient(135deg, #ffffff 0%, #c8d2ff 60%, #b58cff 100%);
  -webkit-background-clip: text;
  background-clip: text;
  color: transparent;
}

.hero p {
  color: var(--text-muted);
  margin: 0;
  font-size: 16px;
}

.faq {
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.example {
  background: linear-gradient(180deg, var(--bg-2), var(--bg-1));
  border: 1px solid var(--border);
  border-radius: 14px;
  overflow: hidden;
  transition: border-color 160ms ease, box-shadow 160ms ease,
    transform 160ms ease;
}

.example:hover {
  border-color: var(--border-strong);
}

.example.is-open {
  border-color: rgba(124, 156, 255, 0.45);
  box-shadow: var(--shadow), 0 0 0 1px rgba(124, 156, 255, 0.15);
}

.faq-question {
  width: 100%;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  background: transparent;
  border: 0;
  color: var(--text);
  padding: 18px 20px;
  text-align: left;
  font-size: 16px;
  font-weight: 600;
  cursor: pointer;
  font-family: inherit;
}

.faq-question:focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: -2px;
}

.faq-question .q-text {
  display: flex;
  align-items: center;
  gap: 12px;
}

.faq-question .q-icon {
  width: 28px;
  height: 28px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  border-radius: 8px;
  background: var(--bg-3);
  border: 1px solid var(--border);
  color: var(--accent);
  flex-shrink: 0;
}

.chev {
  width: 18px;
  height: 18px;
  color: var(--text-muted);
  transition: transform 200ms ease, color 200ms ease;
  flex-shrink: 0;
}

.example.is-open .chev {
  transform: rotate(180deg);
  color: var(--accent);
}

.details {
  display: grid;
  grid-template-rows: 0fr;
  transition: grid-template-rows 220ms ease;
}

.example.is-open .details {
  grid-template-rows: 1fr;
}

.details-inner {
  overflow: hidden;
  color: var(--text-muted);
  font-size: 15px;
  line-height: 1.65;
}

.details-inner > div {
  padding: 0 20px 20px 60px;
  border-top: 1px solid var(--border);
  padding-top: 16px;
}

.details-inner p {
  margin: 0 0 10px;
}

.details-inner p:last-child {
  margin-bottom: 0;
}

.footer {
  margin-top: 48px;
  text-align: center;
  color: var(--text-muted);
  font-size: 13px;
}

@media (max-width: 600px) {
  .hero h1 { font-size: 30px; }
  .page { padding: 40px 16px 64px; }
  .details-inner > div { padding-left: 20px; }
}
